from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            moves = 0
            carried = 0

            for i, p in enumerate(points):
                need = (target + p - 1) // p
                need = max(need - carried, 0)

                if i == n - 1:
                    moves += need
                else:
                    moves += 2 * need - 1
                    carried = max(need - 1, 0)

                if moves > m:
                    return False

            return True

        left, right = 0, min(points) * m

        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1

        return left
